{
  "type": "Comparison table of six portrait styles",
  "subject": "The same middle-aged South Korean mother is presented in six unique visual styles.",
  "identity": {
    "person": "{argument name=\"character identity\" default=\"Mother\"}",
    "gender": "woman",
    "age": "middle aged",
    "ethnicity": "Koreans",
    "hair": "Dark brown to black, medium length, styled in soft waves or an updo depending on the look.",
    "expression": "Calm, gentle, contemplative"
  },
  "layout": {
    "background": "Clean white pages, narrow spacing",
    "grid": {
      "rows": 2,
      "columns": 3,
      "count": 6
    },
    "sections": [
      {
        "position": "Top left",
        "count": 1,
        "label": "Oil portrait",
        "description": "A melancholic classical oil painting, a three-quarter profile half-length portrait, a deep and soft brown-black background, gentle chiaroscuro, a high-necked beige shirt with a subtle sheen, and loosely styled dark hair; masterful brushstrokes, elegant and restrained."
      },
      {
        "position": "Upper-middle",
        "count": 1,
        "label": "Light Watercolor Portrait",
        "description": "A soft watercolor half-length portrait, frontal view, against an airy, pale pink floral background with a cherry blossom-like rendering effect. The wearer wears a loose white shirt with delicate edges, and her skin tone is semi-transparent, creating a bright spring atmosphere."
      },
      {
        "position": "Top right",
        "count": 1,
        "label": "Sunlight scene by the window",
        "description": "A full-length or three-quarter portrait of a woman sitting by an open window, wearing a light blue short-sleeved dress, with pure white curtains fluttering inwards. A terracotta potted plant sits on the windowsill, bathed in warm sunlight, with the rooftops of a city street visible outside. The painting has a realistic style that evokes a tranquil summer atmosphere."
      },
      {
        "position": "Bottom left",
        "count": 1,
        "label": "Stills from the 1990s",
        "description": "A cinematic, realistic portrait reminiscent of a 1995 Korean drama, featuring shoulder-length, softly layered hair, a burgundy knitted turtleneck sweater, warm backlighting and shallow depth of field, an indoor setting with luminous highlights, and a nostalgic, simulated film texture."
      },
      {
        "position": "Middle to lower",
        "count": 1,
        "label": "Ink painting portrait in Korean traditional clothing",
        "description": "A minimalist Korean ink and wash portrait, a three-quarter profile half-body portrait, featuring a white hanbok top with a black collar decoration, loosely styled hair in a low bun, ample negative space, soft brushstrokes, understated traditional elegance, and a small red seal in the corner."
      },
      {
        "position": "Bottom right",
        "count": 1,
        "label": "Fashion Illustration",
        "description": "A highly expressive fashion sketch, featuring a captivating 1980s-inspired look: voluminous dark curls, pearl earrings, a structured rose-pink satin jacket or dress with wide shoulders, a deep V-neck, loose, impressionistic ink lines and blush brushstrokes, all against an off-white paper background."
      }
    ]
  },
  "style": {
    "overall": "A selection of contrasting artistic interpretations of the same woman",
    "quality": "High quality and exquisite design; each of the six panels has a distinct visual appearance but maintains a consistent identity.",
    "face_consistency": "Maintain consistency in facial structure and recognizable mother image across each panel.",
    "color_palette": "Soft classic browns, light pinks and creams, sky blues, burgundys, dark grays, and dusty pinks."
  },
  "camera_and_composition": "Each panel features a vertical layout with the main subject centered, presented in an editable, formatted style.",
  "rendering": "A sophisticated blend of painting and photography aesthetics for each panel, with delicate textures and soft, natural light where appropriate."
}

